from jsonb_to_recordset($json$[{"id":"che-ek-236","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For the second-order process 2A → products, half-life and initial concentration are related by","options":["$t_{1/2} = 1 / (k[\\mathrm{A}]_0)$","$t_{1/2} = \\ln 2 / k$","$t_{1/2} = [\\mathrm{A}]_0 / (2k)$","$t_{1/2} = k[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"Set [A] = [A]$_0$/2 in $1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$ to obtain $t_{1/2} = 1/(k[\\mathrm{A}]_0)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-237","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"After $n$ successive half-lives of a first-order reaction the fraction of reactant left is","options":["$(1/2)^n$","$n/2$","$1/n$","$2^n$"],"answer_index":0,"explanation":"Each half-life halves what remains, so the leftover fraction is $2^{-n}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-238","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A straight line is obtained when $\\ln[\\mathrm{A}]$ is plotted against time for a reaction that is","options":["first order in A","zero order in A","second order in A","third order in A"],"answer_index":0,"explanation":"The first-order integrated law is $\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-239","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A plot of [A] versus time is linear with a negative slope when the reaction is","options":["zero order in A","first order in A","second order in A","fractional order ½"],"answer_index":0,"explanation":"[A] = [A]$_0 - kt$ is the equation of a straight line of slope $-k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-240","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A graph of $1/[\\mathrm{A}]$ versus time is a straight line when the decay of A is","options":["second order","first order","zero order","a pure nuclear explosion"],"answer_index":0,"explanation":"The second-order integrated law is linear in $1/[\\mathrm{A}]$, with slope $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-241","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a first-order reaction has consumed 75% of the reactant, the number of half-lives that have elapsed is","options":["two","one","three","four"],"answer_index":0,"explanation":"75% consumed means 25% remains, which is $(1/2)^2$ of the start, i.e. two half-lives.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-242","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Radioactive disintegration is treated kinetically as","options":["first order in the amount of nuclide","zero order in every case","second order in the daughter nuclide","third order in the neutron number"],"answer_index":0,"explanation":"Each nucleus decays independently, so the rate is proportional to the number remaining: first-order kinetics.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-243","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The half-life of a zero-order reaction with rate constant $k$ equals","options":["$[\\mathrm{A}]_0/(2k)$","$\\ln 2 / k$","$1/(k[\\mathrm{A}]_0)$","$2k/[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"Set $[\\mathrm{A}] = [\\mathrm{A}]_0/2$ in $[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$ to obtain $t_{1/2} = [\\mathrm{A}]_0/(2k)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-244","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order process never quite reaches 100% conversion because","options":["the rate keeps falling as [A] falls, so a finite time cannot exhaust the last traces","the integrated law forbids $t > t_{1/2}$","zero-order kinetics take over near the end","$k$ becomes infinite as [A] approaches zero"],"answer_index":0,"explanation":"[A] = [A]$_0 e^{-kt}$ approaches zero only as $t \\to \\infty$. In practice the reactant becomes undetectable, but the law has no finite finish time.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-245","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order gas reaction has $k = 1.386 \\times 10^{-2}\\ \\mathrm{min^{-1}}$. Its half-life is","options":["50 min","0.693 min","72 min","100 min"],"answer_index":0,"explanation":"$t_{1/2} = 0.693/k = 0.693/(1.386 \\times 10^{-2}) = 50\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
